func (o *InstalledMod) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "GameServer":
		rel, ok := retrieved.(*GameServer)
		if !ok {
			return fmt.Errorf("installedMod cannot load %T as %q", retrieved, name)
		}

		o.R.GameServer = rel
		o.R.Loaded.GameServer = true

		if rel != nil {
			rel.R.InstalledMods = InstalledModSlice{o}
		}
		return nil
	case "InstalledModFiles":
		rels, ok := retrieved.(InstalledModFileSlice)
		if !ok {
			return fmt.Errorf("installedMod cannot load %T as %q", retrieved, name)
		}

		o.R.InstalledModFiles = rels
		o.R.Loaded.InstalledModFiles = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.InstalledMod = o
				rel.R.Loaded.InstalledMod = true
			}
		}
		return nil
	default:
		return fmt.Errorf("installedMod has no relationship %q", name)
	}
}

type installedModPreloader struct {
	GameServer func(...sqlite.PreloadOption) sqlite.Preloader
}

func buildInstalledModPreloader() installedModPreloader {
	return installedModPreloader{
		GameServer: func(opts ...sqlite.PreloadOption) sqlite.Preloader {
			return sqlite.Preload[*GameServer, GameServerSlice](sqlite.PreloadRel{
				Name: "GameServer",
				Sides: []sqlite.PreloadSide{
					{
						From:        InstalledMods,
						To:          GameServers,
						FromColumns: []string{"game_server_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, GameServers.Columns.Names(), opts...)
		},
	}
}

type installedModThenLoader[Q orm.Loadable] struct {
	GameServer        func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	InstalledModFiles func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildInstalledModThenLoader[Q orm.Loadable]() installedModThenLoader[Q] {
	type GameServerLoadInterface interface {
		LoadGameServer(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type InstalledModFilesLoadInterface interface {
		LoadInstalledModFiles(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return installedModThenLoader[Q]{
		GameServer: thenLoadBuilder[Q](
			"GameServer",
			func(ctx context.Context, exec bob.Executor, retrieved GameServerLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadGameServer(ctx, exec, mods...)
			},
		),
		InstalledModFiles: thenLoadBuilder[Q](
			"InstalledModFiles",
			func(ctx context.Context, exec bob.Executor, retrieved InstalledModFilesLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadInstalledModFiles(ctx, exec, mods...)
			},
		),
	}
}

// LoadGameServer loads the installedMod's GameServer into the .R struct
func (o *InstalledMod) LoadGameServer(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.GameServer = nil
	o.R.Loaded.GameServer = false

	related, err := o.GameServer(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.InstalledMods = InstalledModSlice{o}

	o.R.GameServer = related
	o.R.Loaded.GameServer = true
	return nil
}

// LoadGameServer loads the installedMod's GameServer into the .R struct
func (os InstalledModSlice) LoadGameServer(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	gameServers, err := os.GameServer(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.GameServer = nil
		o.R.Loaded.GameServer = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	installedModByKey := make(map[string][]*InstalledMod, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		installedModByKey[o.GameServerID] = append(installedModByKey[o.GameServerID], o)
	}

	for _, rel := range gameServers {

		owners, ok := installedModByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.GameServer != nil {
				continue
			}

			rel.R.InstalledMods = append(rel.R.InstalledMods, o)

			o.R.GameServer = rel

		}
	}

	return nil
}

// LoadInstalledModFiles loads the installedMod's InstalledModFiles into the .R struct
func (o *InstalledMod) LoadInstalledModFiles(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.InstalledModFiles = nil
	o.R.Loaded.InstalledModFiles = false

	related, err := o.InstalledModFiles(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.InstalledMod = o
		rel.R.Loaded.InstalledMod = true
	}

	o.R.InstalledModFiles = related
	o.R.Loaded.InstalledModFiles = true
	return nil
}

// LoadInstalledModFiles loads the installedMod's InstalledModFiles into the .R struct
func (os InstalledModSlice) LoadInstalledModFiles(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	installedModFiles, err := os.InstalledModFiles(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.InstalledModFiles = nil
		o.R.Loaded.InstalledModFiles = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	installedModByKey := make(map[string][]*InstalledMod, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		installedModByKey[o.ID] = append(installedModByKey[o.ID], o)
	}

	for _, rel := range installedModFiles {

		owners, ok := installedModByKey[rel.InstalledModID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.InstalledMod = o
			rel.R.Loaded.InstalledMod = true

			o.R.InstalledModFiles = append(o.R.InstalledModFiles, rel)

		}
	}

	return nil
}

// installedModC is where relationship counts are stored.
type installedModC struct {
	InstalledModFiles *int64
}

// PreloadCount sets a count in the C struct by name
func (o *InstalledMod) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "InstalledModFiles":
		o.C.InstalledModFiles = &count
	}
	return nil
}

type installedModCountPreloader struct {
	InstalledModFiles func(...bob.Mod[*dialect.SelectQuery]) sqlite.Preloader
}

func buildInstalledModCountPreloader() installedModCountPreloader {
	return installedModCountPreloader{
		InstalledModFiles: func(mods ...bob.Mod[*dialect.SelectQuery]) sqlite.Preloader {
			return countPreloader[*InstalledMod]("InstalledModFiles", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = InstalledMods.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(sqlite.Raw("count(*)")),

					sm.From(InstalledModFiles.NameAsExpr()),
					sm.Where(sqlite.Quote(InstalledModFiles.Alias(), "installed_mod_id").EQ(sqlite.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return sqlite.Group(sqlite.Select(subqueryMods...).Expression)
			})
		},
	}
}

type installedModCountThenLoader[Q orm.Loadable] struct {
	InstalledModFiles func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildInstalledModCountThenLoader[Q orm.Loadable]() installedModCountThenLoader[Q] {
	type InstalledModFilesCountInterface interface {
		LoadCountInstalledModFiles(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return installedModCountThenLoader[Q]{
		InstalledModFiles: countThenLoadBuilder[Q](
			"InstalledModFiles",
			func(ctx context.Context, exec bob.Executor, retrieved InstalledModFilesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountInstalledModFiles(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountInstalledModFiles loads the count of InstalledModFiles into the C struct
func (o *InstalledMod) LoadCountInstalledModFiles(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.InstalledModFiles(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.InstalledModFiles = &count
	return nil
}

// LoadCountInstalledModFiles loads the count of InstalledModFiles for a slice in a single batch query
func (os InstalledModSlice) LoadCountInstalledModFiles(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs
	PKArgSlice := make([]bob.Expression, 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		PKArgSlice = append(PKArgSlice, sqlite.Arg(o.ID))
	}
	PKArgExpr := sqlite.Group(PKArgSlice...)

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    string
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			InstalledModFiles.Columns.InstalledModID.As("id"),
			sqlite.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(InstalledModFiles.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(InstalledModFiles.Columns.InstalledModID.OP("IN", PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(InstalledModFiles.Columns.InstalledModID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		sqlite.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[string]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.InstalledModFiles = &count
	}

	return nil
}

type installedModJoins[Q dialect.Joinable] struct {
	typ               string
	GameServer        modAs[Q, gameServerColumns]
	InstalledModFiles modAs[Q, installedModFileColumns]
}

func (j installedModJoins[Q]) aliasedAs(alias string) installedModJoins[Q] {
	return buildInstalledModJoins[Q](buildInstalledModColumns(alias), j.typ)
}

func buildInstalledModJoins[Q dialect.Joinable](cols installedModColumns, typ string) installedModJoins[Q] {
	return installedModJoins[Q]{
		typ: typ,
		GameServer: modAs[Q, gameServerColumns]{
			c: GameServers.Columns,
			f: func(to gameServerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, GameServers.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.GameServerID),
					))
				}

				return mods
			},
		},
		InstalledModFiles: modAs[Q, installedModFileColumns]{
			c: InstalledModFiles.Columns,
			f: func(to installedModFileColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, InstalledModFiles.NameExpr().As(to.Alias())).On(
						to.InstalledModID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
